def transform(wb):
    ws = wb["Worksheet1"]
    last_row = ws.max_row
    if last_row > 10411:
        last_row = 10411
    if last_row < 2:
        return
    sheet_values = cached_values.get("Worksheet1", {})
    blocks = []
    current = None
    for r in range(2, last_row + 1):
        v = sheet_values.get(f"B{r}")
        if v is None:
            v = ws.cell(row=r, column=2).value
        keep = False
        if v is not None:
            s = str(v).upper()
            if s and (s[0] == "H" or s[0] == "A"):
                keep = True
        if keep:
            if current is not None:
                blocks.append([current[0], current[1]])
                current = None
        else:
            if current is None:
                current = [r, r]
            else:
                current[1] = r
    if current is not None:
        blocks.append([current[0], current[1]])
    blocks.reverse()
    for block in blocks:
        ws.delete_rows(block[0], block[1] - block[0] + 1)
